package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReaderBasedJsonParser#getTokenLocation
 */
public class ReaderBasedJsonParser_getTokenLocation_TriageGen0Test {

    private IOContext mockIoContext;
    private ObjectCodec mockCodec;
    private StringReader reader;
    private ReaderBasedJsonParser parser;
    private final Object sourceRef = new Object();

    @Before
    public void setUp() throws IOException {
        mockIoContext = Mockito.mock(IOContext.class);
        mockCodec = Mockito.mock(ObjectCodec.class);
        reader = new StringReader("{\"key\": 123}");

        // Setup IOContext to return a specific source reference
        when(mockIoContext.getSourceReference()).thenReturn(sourceRef);

        // Initialize the parser using the provided constructor signature
        // Note: Since ReaderBasedJsonParser is a concrete implementation, we use its constructor.
        // We use a minimal setup to reach the getTokenLocation method.
        parser = new ReaderBasedJsonParser(
                mockIoContext,
                0,
                reader,
                mockCodec,
                new com.fasterxml.jackson.core.io.BytecharsToNameCanonicalizer()
        );
    }

    @Test
    public void testGetTokenLocation_ReturnsCorrectValues() throws IOException {
        // Advance the parser to a known token position
        // The first token should be the START_OBJECT '{'
        JsonToken token = parser.nextToken();

        assertEquals(JsonToken.START_OBJECT, token);

        JsonLocation location = parser.getTokenLocation();

        // Assertions to verify line, column, offset and source reference
        assertNotNull("JsonLocation should not be null", location);
        assertEquals("Source reference should match", sourceRef, location.getSourceRef());
        assertEquals("Byte offset in JsonLocation should be -1L per implementation", -1L, location.getByteOffset());
        assertEquals("Character offset should match parser state", parser.getTokenCharacterOffset(), location.getCharOffset());
        assertEquals("Line number should match parser state", parser.getTokenLineNr(), location.getLineNr());
        assertEquals("Column number should match parser state", parser.getTokenColumnNr(), location.getColumnNr());
    }

    @Test
    public void testGetTokenLocation_AfterParsingValue() throws IOException {
        // Move to START_OBJECT
        parser.nextToken(); 
        // Move to FIELD_NAME "key"
        parser.nextToken(); 
        // Move to VALUE_NUMBER_INT 123
        parser.nextToken(); 

        JsonLocation location = parser.getTokenLocation();

        assertNotNull(location);
        assertEquals(sourceRef, location.getSourceRef());
        assertEquals(-1L, location.getByteOffset());
        assertEquals(parser.getTokenCharacterOffset(), location.getCharOffset());
        assertEquals(parser.getTokenLineNr(), location.getLineNr());
        assertEquals(parser.getTokenColumnNr(), location.getColumnNr());
    }

    @Test
    public void testGetTokenLocation_WithMultilineInput() throws IOException {
        String multilineJson = "{\n  \"key\": 123\n}";
        StringReader multilineReader = new StringReader(multilineJson);

        ReaderBasedJsonParser multilineParser = new ReaderBasedJsonParser(
                mockIoContext,
                0,
                multilineReader,
                mockCodec,
                new com.fasterxml.jackson.core.io.BytecharsToNameCanonicalizer()
        );

        // Move to the field name which is on line 2
        multilineParser.nextToken(); // {
        multilineParser.nextToken(); // "key"

        JsonLocation location = multilineParser.getTokenLocation();

        assertNotNull(location);
        assertEquals(2, location.getLineNr());
        assertEquals(multilineParser.getTokenCharacterOffset(), location.getCharOffset());
    }
}
